// Vital-side code (includes the imported headers). No file, no preset, no third-party content: every table is computed from the
// formulas in vital_tables.cpp. The order and the names are the choice lists of core/src/param_table.cpp (oscN.wavetable,
// lfoN.shape).
#pragma once

#include <memory>
#include <vector>

#include "line_generator.h"
#include "synthyboy/params.h"
#include "wavetable.h"

namespace synthyboy
{
namespace vitaltables
{
/** Frames of the morphing wavetables (the single cycle shapes at the start of the list have one frame). */
constexpr int kMorphFrames = 64;

/** The built-in wavetables, built once by prepare() (allocation allowed there) and read-only afterwards. Each entry owns its data. */
class WavetableSet
{
public:
    WavetableSet();

    int size() const noexcept { return static_cast<int> (tables.size()); }
    /** The data of entry index (clamped); valid as long as the set lives. */
    sbvital::Wavetable::WavetableData* data (int index) noexcept;
    int numFrames (int index) const noexcept;

private:
    std::vector<std::unique_ptr<sbvital::Wavetable>> tables;
};

/** Sets an LFO's line to the built-in shape (0 .. kNumLfoShapes - 1) and renders it. No allocation. */
void applyLfoShape (LineGenerator& line, int shape) noexcept;

/** Time domain samples (one cycle, 2048 values) of a built-in wavetable frame, for tests. */
void renderFrame (int table, int frame, float* out2048);
} // namespace vitaltables
} // namespace synthyboy
